~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_175210C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_175210C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_175210C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_175214C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_175214C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_175214C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_175100C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_175100C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_175100C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_17513cC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_17513cC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_17513cC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_175104C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_175104C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_175104C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_175108C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_175108C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_175108C1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8W_17510cC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8F_17510cC1?~~~~~~~~~~~~~~~C69OSSVerify5KrLib3bpA5Start@Asan_code_memcpy8D_17510cC1?~~~~~~~~~~~~~~~".
Import ListNotations.
Open Scope bv_scope.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section ALL.
  Variable mem0 : word -> option byte.
  Variables dst src : word.
  Variable n : Z.
  Variable bs : list byte.
  Variable rom : word -> option byte.
  Hypothesis HOK : mcH mem0 dst src n bs.

  #[local] Notation MK := (memk mem0 dst bs).
  #[local] Notation SB := (sb_ bs).
  #[local] Notation B := (b_ bs).
  Let Hn0 : (0 <= n < 2 ^ 64)%Z := Hn _ _ _ _ _ HOK.
  Let Hnws : (bv_unsigned src + n < 2 ^ 64)%Z := Hnws _ _ _ _ _ HOK.
  Let Hnwd : (bv_unsigned dst + n < 2 ^ 64)%Z := Hnwd _ _ _ _ _ HOK.

  Ltac mlw F D jj :=
    chain_step; [reflexivity
      | eapply (mc_lw _ _ _ _ _ HOK) with (j := jj);
        [exact F | reflexivity | exact D | gres; rwH; rewrite ?at_addi; reflexivity | imm_norm; lia | lia | lia | lia]
      | step_simpl]; vnorm.
  Ltac mlbu F D jj :=
    chain_step; [reflexivity
      | eapply (mc_lbu _ _ _ _ _ HOK) with (j := jj);
        [exact F | reflexivity | exact D | gres; rwH; rewrite ?at_addi; reflexivity | imm_norm; lia | lia | lia | lia]
      | step_simpl]; vnorm.

  Ltac mk_at kk := match goal with |- msteps _ (mkst _ _ (MK ?a) _) _ =>
                     first [constr_eq a kk | replace (MK a) with (MK kk) by (f_equal; lia)] end.
  Ltac msw F D kk valtac :=
    mk_at kk;
    chain_step; [reflexivity
      | eapply (mc_sw _ _ _ _ _ HOK) with (k := kk);
        [exact F | reflexivity | exact D | gres; rwH; rewrite ?at_addi; reflexivity | imm_norm; lia
        | gres; rwH; reflexivity | valtac | lia | lia]
      | step_simpl].
  Ltac msb F D kk valtac :=
    mk_at kk;
    chain_step; [reflexivity
      | eapply (mc_sb _ _ _ _ _ HOK) with (k := kk);
        [exact F | reflexivity | exact D | gres; rwH; rewrite ?at_addi; reflexivity | imm_norm; lia
        | gres; rwH; reflexivity | valtac | lia | lia]
      | step_simpl].

  Ltac cond :=
    rwH; unfold c_eq, c_ltu, bv_eqb, bv_ltu; rewrite ?u_andi by lia; imm_norm; unorm;
    first [apply Z.eqb_eq | apply Z.eqb_neq | apply Z.ltb_lt | apply Z.ltb_ge];
    rewrite ?land_3 by lia; lia.
  Ltac mk_eq := match goal with |- context [mkst _ _ (MK ?a) _] =>
                  match goal with |- msteps _ _ (mkst _ _ (MK ?b) _) => replace (MK a) with (MK b) by (f_equal; lia) end end.

  Ltac post := repeat split; gres; rwH; rewrite ?at_addi; try (f_equal; lia); try reflexivity; try solve_keeps.

  Ltac conda := rwH; unfold at_; cond.

  Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).

  Lemma al_finish : forall regs (ret : word) k,
    ret_ok ret -> getr regs 1 = ret ->
    getr regs 11 = at_ src k -> getr regs 13 = at_ dst k -> getr regs 12 = Z_to_bv 64 (n - k) ->
    (0 <= k <= n)%Z ->
    exists regs',
      msteps ASEGS (mkst regs (0x17521c : word) (MK k) rom) (mkst regs' ret (MK n) rom)
